(() => {
'use strict';
const RELEASE='20260905-21';
const dataPath=document.documentElement.dataset.dataPath||'assets/projects.json';
const baseDir=dataPath.replace(/projects\.json$/,'');
const paths={base:dataPath,refresh:`${baseDir}portfolio-refresh.json`,pricing:`${baseDir}pricing-review.json`,live:`${baseDir}live-release.json`};
const STATUS={V:'Software-Validated',P:'Verified Prototype',R:'Research'};
const POTENTIAL={VH:'Very High',H:'High',M:'Moderate',S:'Specialist'};
const SAFE=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const EUR=v=>new Intl.NumberFormat('nl-NL',{style:'currency',currency:'EUR',maximumFractionDigits:0}).format(Number(v)||0);
const USD=(v,r)=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format((Number(v)||0)*r);
async function load(path){const r=await fetch(`${path}?v=${RELEASE}`,{cache:'no-store'});if(!r.ok)throw new Error(`Unable to load ${path}`);return r.json()}
function build(base,refresh,pricing,live){const merged=JSON.parse(JSON.stringify(base));for(const c of refresh.replacements||[]){const row=merged.a.find(x=>x[0]===c.id);if(!row)throw new Error(`Missing historical replacement ${c.id}`);row[2]=c.slug;row[3]=c.name;row[6]=c.summary}const refs=new Set(merged.a.map(x=>x[1]));for(const row of refresh.additions||[])if(!refs.has(row[1]))merged.a.push(row);for(const c of live.replacements||[]){const row=merged.a.find(x=>x[0]===c.id);if(!row)throw new Error(`Missing current replacement ${c.id}`);row[2]=c.slug;row[3]=c.name;row[6]=c.summary}const prices=new Map((pricing.records||[]).map(x=>[x[0],x]));const assets=merged.a.map(row=>{const p=prices.get(row[0]);if(!p)throw new Error(`Missing pricing ${row[0]}`);return{id:row[0],ref:row[1],slug:row[2],name:row[3],category:merged.c[row[4]],statusCode:row[5],status:STATUS[row[5]],summary:row[6],ask:Number(p[1]),priceLow:Number(p[2]),priceHigh:Number(p[3]),quick:Number(p[4]),rd:Number(row[8]),potentialCode:row[9],potential:POTENTIAL[row[9]],route:merged.r[row[10]],externalUrl:row[11]||''}});for(const x of live.additions||[])assets.push({...x,status:STATUS[x.statusCode],potential:POTENTIAL[x.potentialCode],externalUrl:x.externalUrl||''});for(const a of assets)a.auditNote=live.audit_notes?.[String(a.id)]||'';assets.sort((a,b)=>a.id-b.id);return assets}
function validate(assets,live){const e=live.expected,sum=k=>assets.reduce((n,x)=>n+Number(x[k]),0),count=k=>assets.reduce((m,x)=>(m[x[k]]=(m[x[k]]||0)+1,m),{}),sc=count('statusCode'),pc=count('potentialCode');const sequential=assets.every((x,i)=>x.id===i+1&&x.ref===`TA-IP-${String(i+1).padStart(3,'0')}`);const out={ask:sum('ask'),rd:sum('rd'),low:sum('priceLow'),high:sum('priceHigh'),quick:sum('quick'),sc,pc};out.passed=assets.length===live.repository_scope.canonical_assets&&new Set(assets.map(x=>x.slug)).size===assets.length&&new Set(assets.map(x=>x.ref)).size===assets.length&&sequential&&out.ask===e.strategic_asking_reference&&out.rd===e.recreation_cost_reference&&out.low===e.strategic_band[0]&&out.high===e.strategic_band[1]&&out.quick===e.quick_sale_reference&&['V','P','R'].every(k=>(sc[k]||0)===e.status_counts[k])&&['VH','H','M','S'].every(k=>(pc[k]||0)===e.potential_counts[k])&&assets.every(x=>x.ask>0&&x.rd>=x.ask&&x.priceLow<=x.ask&&x.ask<=x.priceHigh&&x.quick<=x.ask);return out}
function set(id,v){const e=document.getElementById(id);if(e)e.textContent=v}
function renderHome(data){const {assets,live,v}=data,rate=live.fx.rate;set('asset-count',assets.length);set('observed-count',live.repository_scope.private_project_repositories_observed);set('validated-count',v.sc.V||0);set('prototype-count',v.sc.P||0);set('research-count',v.sc.R||0);set('ask-total',EUR(v.ask));set('ask-total-usd',`≈ ${USD(v.ask,rate)} USD`);set('rd-total',EUR(v.rd));set('rd-total-usd',`≈ ${USD(v.rd,rate)} USD`);set('fx-rate',`1 EUR = ${rate.toFixed(4)} USD`);set('strategic-band',`${EUR(v.low)} – ${EUR(v.high)}`);set('quick-sale',EUR(v.quick));set('value-ratio',`${(v.ask/v.rd*100).toFixed(1)}%`);set('release-status',v.passed?'Register checks passed':'Register review required');const rs=document.getElementById('release-status');if(rs)rs.dataset.ok=v.passed?'true':'false';const scope=document.getElementById('repository-scope');if(scope)scope.innerHTML=`<div class="scope-item"><span>Private project repositories observed</span><strong>${live.repository_scope.private_project_repositories_observed}</strong></div><div class="scope-item"><span>Canonical portfolio assets</span><strong>${live.repository_scope.canonical_assets}</strong></div><div class="scope-item"><span>Retained legacy migration repository</span><strong>${live.repository_scope.legacy_private_repositories_retained}</strong></div>`;const updates=document.getElementById('release-updates');if(updates){const current=(live.current_update_ids||[]).map(id=>assets.find(x=>x.id===id)).filter(Boolean);updates.innerHTML=current.map(a=>`<article class="update-card"><span class="asset-ref">${SAFE(a.ref)}</span><h3>${SAFE(a.name)}</h3><p>${SAFE(a.auditNote||a.summary)}</p></article>`).join('')}const grid=document.getElementById('project-grid'),filters=document.getElementById('filters'),search=document.getElementById('search'),sort=document.getElementById('sort'),count=document.getElementById('result-count');if(!grid||!filters)return;let active='all';const defs=[['all','All assets'],['current','Current update'],['V','Software-Validated'],['P','Verified Prototype'],['R','Research']];filters.innerHTML=defs.map(([x,l],i)=>`<button type="button" class="filter${i?'':' active'}" data-filter="${x}" aria-pressed="${i?'false':'true'}">${l}</button>`).join('');filters.addEventListener('click',e=>{const b=e.target.closest('button[data-filter]');if(!b)return;active=b.dataset.filter;filters.querySelectorAll('button').forEach(x=>{const on=x===b;x.classList.toggle('active',on);x.setAttribute('aria-pressed',on?'true':'false')});draw()});const match=a=>active==='all'||(active==='current'&&(live.current_update_ids||[]).includes(a.id))||a.statusCode===active;function card(a){return`<article class="asset-card"><div class="asset-card-top"><span class="asset-ref">${SAFE(a.ref)}</span><span class="status status-${a.statusCode}">${SAFE(a.status)}</span></div><div><h3>${SAFE(a.name)}</h3><p class="asset-summary">${SAFE(a.summary)}</p></div><div class="asset-meta"><span>${SAFE(a.category)}</span><span>${SAFE(a.route)}</span><span>Potential: ${SAFE(a.potential)}</span></div><div class="price-block"><div><span>Strategic asking reference</span><strong>${EUR(a.ask)}</strong><small>≈ ${USD(a.ask,rate)} USD</small></div><div><span>Recreation-cost reference</span><strong>${EUR(a.rd)}</strong><small>≈ ${USD(a.rd,rate)} USD</small></div></div><details><summary>Pricing & evidence boundary</summary><div class="detail-grid"><p><strong>Strategic band</strong><br>${EUR(a.priceLow)} – ${EUR(a.priceHigh)}</p><p><strong>Liquidity reference</strong><br>${EUR(a.quick)}</p><p><strong>Maturity</strong><br>${SAFE(a.status)}</p><p><strong>Boundary</strong><br>Internal evidence is not independent certification, legal title or market traction.</p></div></details><a class="profile-link" href="projects/${SAFE(a.slug)}/">Open asset profile →</a>${a.externalUrl?`<a class="text-link" href="${SAFE(a.externalUrl)}" target="_blank" rel="noopener">Open public product site ↗</a>`:''}</article>`}function draw(){const q=(search?.value||'').trim().toLowerCase();const rows=assets.filter(a=>match(a)&&(!q||`${a.ref} ${a.name} ${a.category} ${a.summary} ${a.route} ${a.status}`.toLowerCase().includes(q)));const mode=sort?.value||'ask-desc';if(mode==='name')rows.sort((a,b)=>a.name.localeCompare(b.name));else if(mode==='ask-asc')rows.sort((a,b)=>a.ask-b.ask);else if(mode==='newest')rows.sort((a,b)=>b.id-a.id);else rows.sort((a,b)=>b.ask-a.ask);grid.innerHTML=rows.map(card).join('');if(count)count.textContent=`${rows.length} of ${assets.length} assets`}search?.addEventListener('input',draw);sort?.addEventListener('change',draw);draw()}
function renderDetail(data){const pathSlug=location.pathname.split('/').filter(Boolean).at(-1)||'';const slug=document.documentElement.dataset.asset||pathSlug;if(!slug||slug==='MyProjects')return;const root=document.getElementById('project');if(!root)return;const aliases={'systemic-absolute-topology':'continuum-state-integrity-platform','lewis-hybrid-llm-orchestrator':'resource-aware-hybrid-model-orchestration-platform','sentinelbio-verify':'biometric-systems-assurance-platform','agentic-engineering-control-plane':'evidence-governed-software-assurance-platform','best-of-github-agentic-engineering':'evidence-governed-software-assurance-platform','axiomcrypt':'modular-key-cryptanalysis-platform','shield-breaker-research':'protein-structure-evidence-qualification-platform','titan-evtol-research-platform':'electric-flight-systems-simulation-validation-platform','chimera-spectral-perception-system':'vision-evidence-governed-multimodal-perception-framework'};const current=aliases[slug]||slug,a=data.assets.find(x=>x.slug===current);if(!a){root.innerHTML='<section class="shell page-hero"><p class="eyebrow">Portfolio profile</p><h1>Asset not found.</h1><a class="btn" href="../../">Return to portfolio</a></section>';return}const rate=data.live.fx.rate;document.title=`${a.name} — THEARCHITECT_MAX`;const canon=document.querySelector('link[rel="canonical"]');if(canon)canon.href=`https://thearchitect-max.github.io/MyProjects/projects/${a.slug}/`;root.innerHTML=`<header><div class="shell nav"><a class="brand" href="../../"><span class="mark">TA</span><span class="brand-copy"><strong>THEARCHITECT_MAX</strong><span>Private Software/IP Portfolio</span></span></a><nav class="nav-links"><a href="../../#portfolio">Portfolio</a><a href="../../assurance.html">Assurance</a><a href="../../commercialization.html">Valuation</a><a href="../../transfer.html">Transfer</a></nav><a class="btn" href="../../#portfolio">All assets</a></div></header><div class="shell detail-shell"><section class="detail-hero"><div class="statusline"><span class="asset-ref">${SAFE(a.ref)}</span><span class="status status-${a.statusCode}">${SAFE(a.status)}</span><span class="chip">${SAFE(a.category)}</span></div><h1>${SAFE(a.name)}</h1><p class="lede">${SAFE(a.summary)}</p></section><section class="detail-layout"><div class="detail-panel"><h2>Asset profile</h2><div class="fact-list"><div class="fact"><span>Commercial route</span><strong>${SAFE(a.route)}</strong></div><div class="fact"><span>Commercial potential</span><strong>${SAFE(a.potential)}</strong></div><div class="fact"><span>Maturity</span><strong>${SAFE(a.status)}</strong></div><div class="fact"><span>Asset reference</span><strong>${SAFE(a.ref)}</strong></div></div>${a.auditNote?`<div class="audit-note"><strong>Current audit note</strong><br>${SAFE(a.auditNote)}</div>`:''}<div class="notice" style="margin-top:18px"><strong>Evidence boundary.</strong> Portfolio maturity describes observed repository and internal software evidence. It does not establish independent certification, scientific/clinical validity, legal chain-of-title, patent/FTO clearance, regulatory approval, customer traction or transaction value.</div></div><aside class="detail-panel"><h2>Commercial references</h2><div class="price-hero"><div><span>Strategic asking</span><strong>${EUR(a.ask)}</strong><small>≈ ${USD(a.ask,rate)} USD</small></div><div><span>Recreation cost</span><strong>${EUR(a.rd)}</strong><small>≈ ${USD(a.rd,rate)} USD</small></div></div><div class="fact-list" style="margin-top:12px"><div class="fact"><span>Strategic band</span><strong>${EUR(a.priceLow)} – ${EUR(a.priceHigh)}</strong></div><div class="fact"><span>Liquidity reference</span><strong>${EUR(a.quick)}</strong></div><div class="fact"><span>FX reference</span><strong>1 EUR = ${rate.toFixed(4)} USD</strong></div></div>${a.externalUrl?`<a class="btn" style="margin-top:18px" href="${SAFE(a.externalUrl)}" target="_blank" rel="noopener">Open product site ↗</a>`:''}</aside></section></div><footer class="footer"><div class="shell footer-inner"><div><strong>THEARCHITECT_MAX</strong><br>Private software/IP portfolio</div><div>${SAFE(RELEASE)} · EUR authoritative / USD indicative</div></div></footer>`}
async function init(){try{const [base,refresh,pricing,live]=await Promise.all([load(paths.base),load(paths.refresh),load(paths.pricing),load(paths.live)]);const assets=build(base,refresh,pricing,live),v=validate(assets,live),data={base,refresh,pricing,live,assets,v};document.documentElement.dataset.release=RELEASE;document.documentElement.dataset.register=v.passed?'passed':'failed';renderHome(data);renderDetail(data)}catch(err){console.error(err);set('release-status','Register load failed');const g=document.getElementById('project-grid');if(g)g.innerHTML=`<div class="load-error"><strong>Portfolio data could not be loaded.</strong><br>${SAFE(err.message)}</div>`}}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init,{once:true});else init();
})();
